import{apiClient}from"./client";const getConfigurationEnrichments=async()=>{return(await apiClient.get("/admin/configuration-enrichments")).data},getConfigurationEnrichmentTree=async()=>{return(await apiClient.get("/admin/configuration-enrichments/tree")).data},createConfigurationEnrichment=async n=>{return(await apiClient.post("/admin/configuration-enrichments",n)).data},deleteConfigurationEnrichment=async n=>{return(await apiClient.delete("/admin/configuration-enrichments/"+n)).data},updateConfigurationEnrichment=async n=>{return(await apiClient.post("/admin/configuration-enrichments",n)).data};export{getConfigurationEnrichments,getConfigurationEnrichmentTree,createConfigurationEnrichment,deleteConfigurationEnrichment,updateConfigurationEnrichment};